    fallbacks: {},
    html: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"><meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"><title>Enara</title><meta name=\"color-scheme\" content=\"light dark\"><meta name=\"supported-color-schemes\" content=\"light dark\"><style>.logo-dark{display:none!important;}@media (prefers-color-scheme: dark){.logo-light{display:none!important;}.logo-dark{display:block!important;width:120px!important;height:55px!important;max-height:none!important;overflow:visible!important;}}[data-ogsc] .logo-light{display:none!important;}[data-ogsc] .logo-dark{display:block!important;width:120px!important;height:55px!important;max-height:none!important;}</style></head>\n<body style=\"margin:0;padding:0;background-color:#f4f4f2;\">\n<div style=\"display:none;max-height:0;overflow:hidden;\">LMS items that need a look today.</div>\n<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#f4f4f2\" style=\"background-color:#f4f4f2;\"><tr><td align=\"center\" style=\"padding-top:32px;padding-bottom:32px;padding-left:12px;padding-right:12px;\">\n<table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"max-width:600px;\">\n<tr><td align=\"left\" style=\"padding-bottom:24px;text-align:left;\"><img class=\"logo-light\" src=\"https://assets.enara.app/email/enara-logo.png\" width=\"120\" height=\"55\" border=\"0\" alt=\"Enara\" style=\"display:block;width:120px;height:55px;\"><!--[if !mso]><!--><img class=\"logo-dark\" src=\"https://assets.enara.app/email/enara-logo-white.png\" width=\"120\" height=\"55\" border=\"0\" alt=\"Enara\" style=\"display:none;width:0;height:0;max-height:0;overflow:hidden;mso-hide:all;\"><!--<![endif]--></td></tr>\n<tr><td bgcolor=\"#ffffff\" style=\"background-color:#ffffff;border-radius:12px;padding-top:36px;padding-bottom:36px;padding-left:32px;padding-right:32px;\">\n<h1 style=\"font-family:Arial, Helvetica, sans-serif;font-size:24px;line-height:32px;color:#111111;margin-top:0;margin-bottom:16px;font-weight:bold;\">LMS daily summary</h1><p style=\"font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:24px;color:#222222;margin-top:0;margin-bottom:16px;\">Everything below covers the last 24 hours ({{{DATE}}}), all schools.</p><table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-bottom:20px;\"><tr><td style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#666666;\">Approvals waiting over 24 h</td><td align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#111111;font-weight:bold;\">{{{PENDING_OVER_24H}}}</td></tr><tr><td style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#666666;\">Schools flagged for billing</td><td align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#111111;font-weight:bold;\">{{{BILLING_FLAGS}}}</td></tr><tr><td style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#666666;\">Grades not sent (all schools, 24 h)</td><td align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#111111;font-weight:bold;\">{{{DEAD_JOBS}}}</td></tr><tr><td style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#666666;\">Roster syncs failed</td><td align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#111111;font-weight:bold;\">{{{ROSTER_FAILED}}}</td></tr><tr><td style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#666666;\">Key problems</td><td align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#111111;font-weight:bold;\">{{{KEY_PROBLEMS}}}</td></tr><tr><td style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#666666;\">Connections switched off</td><td align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#111111;font-weight:bold;\">{{{SWITCHED_OFF}}}</td></tr><tr><td style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#666666;\">Launches from unknown LMSs</td><td align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#111111;font-weight:bold;\">{{{UNKNOWN_LMS_LAUNCHES}}}</td></tr><tr><td style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#666666;\">Highest cookieless share</td><td align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:22px;padding-top:8px;padding-bottom:8px;border-bottom:1px solid #eeeeee;color:#111111;font-weight:bold;\">{{{COOKIELESS_TOP}}}</td></tr></table><table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin-top:8px;margin-bottom:8px;\"><tr><td bgcolor=\"#111111\" style=\"background-color:#111111;border-radius:8px;\"><a href=\"{{{ACTION_URL}}}\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:20px;color:#ffffff;text-decoration:none;font-weight:bold;display:inline-block;padding-top:14px;padding-bottom:14px;padding-left:28px;padding-right:28px;\">Open the LMS admin</a></td></tr></table>\n</td></tr>\n<tr><td align=\"center\" style=\"padding-top:20px;\"><p style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;line-height:18px;color:#888888;margin-top:0;margin-bottom:0;\">Enara internal LMS alert. Do not forward to schools.</p></td></tr>\n</table></td></tr></table></body></html>",
